'use strict';

// Pure module derivation for docs/product/ (spec 023, Wave 2). No fs, no
// clock: callers pass data and `today`. Also hosts the NEXT.md line helpers
// shared by the project NEXT.md (product-derived.cjs) and module NEXT.md, so
// both outputs use one cursor predicate and one set of line formats.
//
// `module` (milestone) and `modules` (roadmap) are read defensively from
// already-parsed frontmatter; validation is the validator's job.

const GENERATED_HEADER =
  '<!-- generated file — do not hand-edit. Regenerated by `a1-tools product ...` -->';

const NO_OPEN_FEATURE_TEXT =
  'None — no open feature in this module (all done/cancelled, or none planned).';
const NO_ELIGIBLE_PROJECT_TEXT =
  'None — no eligible feature (all done/cancelled, or blocked by unmet dependencies).';
const UNASSIGNED = 'unassigned';

function isOpen(feature) {
  return feature.status !== 'done' && feature.status !== 'cancelled';
}

function statusMap(features) {
  return new Map(features.map((f) => [f.id, f.status]));
}

/** Project cursor predicate: open and every depends_on is done. */
function isEligible(feature, statusById) {
  return isOpen(feature) && (feature.depends_on || []).every((d) => statusById.get(d) === 'done');
}

/** First eligible feature (roadmap order) among `candidates`; dependency
 * status is always looked up across ALL features via `statusById`. */
function firstEligible(candidates, statusById) {
  const hit = candidates.find((f) => isEligible(f, statusById));
  return hit ? hit.id : null;
}

function moduleOfMilestone(milestone) {
  return milestone && typeof milestone.module === 'string' && milestone.module !== ''
    ? milestone.module
    : null;
}

function milestonesById(milestones) {
  return new Map(milestones.map((m) => [m.id, m]));
}

/** Module of a feature via its milestone, or null (untagged / unknown). */
function moduleOfFeature(feature, byId) {
  return moduleOfMilestone(byId.get(feature.milestone));
}

/** Ordered module ids in use: `modules:` list order (entries carried by at
 * least one milestone), then tagged ids missing from the list by first
 * appearance. Without a list: first appearance in `milestones`. */
function modulesInUse(roadmapFm) {
  const milestones = Array.isArray(roadmapFm.milestones) ? roadmapFm.milestones : [];
  const tagged = [];
  for (const m of milestones) {
    const mod = moduleOfMilestone(m);
    if (mod !== null && !tagged.includes(mod)) tagged.push(mod);
  }
  const list = Array.isArray(roadmapFm.modules) ? roadmapFm.modules : [];
  const ordered = list.filter((id, i) => tagged.includes(id) && list.indexOf(id) === i);
  return [...ordered, ...tagged.filter((id) => !ordered.includes(id))];
}

function moduleFeatures(moduleId, features, milestones) {
  const byId = milestonesById(milestones);
  return features.filter((f) => moduleOfFeature(f, byId) === moduleId);
}

/** Per-module cursor id or null. Derived only, never stored in frontmatter. */
function moduleCursor(moduleId, features, milestones) {
  return firstEligible(moduleFeatures(moduleId, features, milestones), statusMap(features));
}

/** Why a module has no cursor. `{ kind: 'none-open' }` when it has no open
 * feature; otherwise `{ kind: 'blocked', featureId, depId, depModule,
 * depStatus }` for the first open feature and its first unmet dependency. */
function blockedReason(moduleId, features, milestones) {
  const open = moduleFeatures(moduleId, features, milestones).filter(isOpen);
  if (open.length === 0) return { kind: 'none-open' };
  const byId = milestonesById(milestones);
  const featureById = new Map(features.map((f) => [f.id, f]));
  const first = open[0];
  const depId = (first.depends_on || []).find((d) => {
    const dep = featureById.get(d);
    return !dep || dep.status !== 'done';
  });
  if (depId === undefined) return { kind: 'none-open' };
  const dep = featureById.get(depId);
  return {
    kind: 'blocked',
    featureId: first.id,
    depId,
    depModule: (dep && moduleOfFeature(dep, byId)) || UNASSIGNED,
    depStatus: dep ? dep.status : 'unknown',
  };
}

function blockedText(r) {
  if (r.kind === 'none-open') return NO_OPEN_FEATURE_TEXT;
  return `None — blocked: ${r.featureId} waits for ${r.depId} (module ${r.depModule}, status ${r.depStatus}).`;
}

/** `## Next cursor` body line (project and module format). */
function cursorLine(cursorId, features) {
  const f = features.find((x) => x.id === cursorId);
  const rationale = f && (f.depends_on || []).length > 0
    ? `all dependencies (${f.depends_on.join(', ')}) are done`
    : 'no unmet dependencies, first eligible feature in roadmap order';
  return `**${cursorId}** — recommended next feature (${rationale}).`;
}

function inFlightLines(features) {
  const inFlight = features.filter((f) => f.status === 'in-flight');
  if (inFlight.length === 0) return ['None.'];
  return inFlight.map((f) => {
    const scopeHint = f.spec_path || f.plan_path
      ? ` — scope: ${[f.spec_path, f.plan_path].filter(Boolean).join(', ')}`
      : '';
    return `- **${f.id}** — ${f.title} (milestone: ${f.milestone}, stage: ${f.stage || 'none'})${scopeHint}`;
  });
}

function howToContinueLine(cursorId) {
  return cursorId === null
    ? 'Run `a1-progress` to review overall project state and decide the next milestone.'
    : 'Run `a1-plan` to create an executable plan for the next-cursor feature, or `a1-execute` if a plan already exists.';
}

/** Module NEXT.md text (FR-009). `data` = { features, milestones } where
 * features are the derived feature entries (with milestone/status/depends_on). */
function renderModuleNext(moduleId, data, today) {
  const { features, milestones } = data;
  const own = moduleFeatures(moduleId, features, milestones);
  const cursor = moduleCursor(moduleId, features, milestones);
  const lines = [
    `# NEXT.md — module ${moduleId}`, '', GENERATED_HEADER, '', `updated: ${today}`, '',
    '## In-flight features', '', ...inFlightLines(own),
    '', '## Next cursor', '',
    cursor === null
      ? blockedText(blockedReason(moduleId, features, milestones))
      : cursorLine(cursor, features),
    '', '## How to continue', '', howToContinueLine(cursor), '',
  ];
  return lines.join('\n');
}

/** Lines for the project NEXT.md between `## Next cursor` and `## How to
 * continue` (FR-010). Empty array when no module is in use. */
function projectModuleSections(roadmapFm, features) {
  const mods = modulesInUse(roadmapFm);
  if (mods.length === 0) return [];
  const milestones = Array.isArray(roadmapFm.milestones) ? roadmapFm.milestones : [];
  const lines = ['', '## Next per module', ''];
  for (const mod of mods) {
    const c = moduleCursor(mod, features, milestones);
    lines.push(`- **${mod}** — ${c === null ? 'None' : `**${c}**`}`);
  }
  const untagged = milestones.filter((m) => moduleOfMilestone(m) === null);
  if (untagged.length > 0) {
    lines.push('', '## Unassigned milestones', '');
    for (const m of untagged) lines.push(`- **${m.id}** — ${m.title}`);
  }
  return lines;
}

module.exports = {
  GENERATED_HEADER,
  NO_OPEN_FEATURE_TEXT,
  NO_ELIGIBLE_PROJECT_TEXT,
  isEligible,
  firstEligible,
  statusMap,
  modulesInUse,
  moduleOfFeature,
  moduleCursor,
  blockedReason,
  blockedText,
  cursorLine,
  inFlightLines,
  howToContinueLine,
  renderModuleNext,
  projectModuleSections,
};
